// Find Art icon API: Forma's own index of open-licensed icon sets (no third-party service).
//
//   GET /icons/search?q=&limit=&offset=   -> { icons: [{ id, name, set, license }], total }
//   GET /icons/svg?id=prefix:name          -> image/svg+xml, black fill, 24px tall
//   GET /icons/sets                        -> credits: every set with author and licence
//
// Data is generated by scripts/build-icon-index.mjs into server/icons/ and committed.
// catalog.json (names + keywords) is loaded once per instance on the first search; each
// sets/<prefix>.json (icon bodies) is loaded the first time an icon from that set is drawn.
// vercel.json includes server/icons/** in the api/icons functions, since paths are dynamic.
import { readFile } from 'node:fs/promises'

const DIR = new URL('./icons/', import.meta.url)
const ID_RE = /^([a-z0-9-]{1,40}):([a-z0-9-]{1,80})$/
const MAX_LIMIT = 60

let indexPromise = null
const setCache = new Map()

const readJson = async (rel) => JSON.parse(await readFile(new URL(rel, DIR), 'utf8'))

/** Flat, search-ready view of catalog.json. Built once; ~38k icons takes a few ms. */
function loadIndex() {
  indexPromise ??= readJson('catalog.json')
    .then((catalog) => {
      const sets = catalog.sets
      const bySet = new Map()
      const entries = []
      sets.forEach((s, rank) => {
        const strip = new Set(s.strip)
        bySet.set(s.prefix, { ...s, rank, nameSet: new Set(s.names) })
        for (const n of s.names) {
          const words = n.split('-').filter((w) => !strip.has(w))
          entries.push({
            id: `${s.prefix}:${n}`,
            rank,
            prefix: s.prefix,
            words,
            flat: words.join(''),
            keys: s.keys[n] ? s.keys[n].split(' ') : [],
            outline: n.split('-').some((w) => strip.has(w) && OUTLINE_WORDS.has(w)),
          })
        }
      })
      return { sets, bySet, entries }
    })
    .catch((err) => {
      indexPromise = null // retry on the next request rather than caching the failure
      throw err
    })
  return indexPromise
}

function loadSet(prefix) {
  let p = setCache.get(prefix)
  if (!p) {
    p = readJson(`sets/${prefix}.json`).catch((err) => {
      setCache.delete(prefix)
      throw err
    })
    setCache.set(prefix, p)
  }
  return p
}

/** "Dogs & cats!" -> ["dogs", "cats"]. */
export const queryWords = (q) =>
  String(q)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .split(' ')
    .filter(Boolean)
    .slice(0, 6)

/** How well one query word matches one icon. 0 = no match. */
function wordScore(qw, e) {
  const plural = qw.length > 3 && qw.endsWith('s') ? qw.slice(0, -1) : null
  let best = 0
  for (const w of e.words) {
    if (w === qw || w === plural) return 4
    if (w.startsWith(qw)) best = Math.max(best, 3)
  }
  for (const k of e.keys) {
    if (k === qw || k === plural) best = Math.max(best, 2.5)
    else if (k.startsWith(qw)) best = Math.max(best, 1.5)
  }
  // Compound names: "ball" in "football", "fish" in "goldfish".
  if (!best && qw.length >= 4 && e.flat.includes(qw)) best = 1
  return best
}

// Outline variants rank just below their filled twin: filled art carves as a solid shape.
const OUTLINE_WORDS = new Set(['outline', 'o'])

/**
 * Ranked entries for a query. Icons matching every query word come first; for multi-word
 * queries, icons matching only some of the words follow ("coffee cup" still shows cups).
 */
export function rankIcons(index, q) {
  const qws = queryWords(q)
  if (!qws.length) return []
  const joined = qws.join('')
  const hits = []
  for (const e of index.entries) {
    let score = 0
    let matched = 0
    for (const qw of qws) {
      const s = wordScore(qw, e)
      if (s) matched++
      else if (qws.length === 1) break
      score += s
    }
    if (!matched) continue
    if (e.flat === joined) score += 5 // the icon is exactly what was asked for
    score -= 0.4 * Math.max(0, e.words.length - matched) // "cat" beats "cat-paw-print-off"
    if (e.outline) score -= 0.5
    hits.push({ e, score, matched })
  }
  hits.sort((a, b) => b.matched - a.matched || b.score - a.score || a.e.rank - b.e.rank || a.e.flat.length - b.e.flat.length)
  return diversify(hits.map((h) => h.e))
}

/**
 * Keeps the order but stops one big set filling the first pages: each run of 24 results takes at
 * most 6 from any set while other sets still have matches; the rest follow in their own order.
 */
function diversify(list, window = 24, perSet = 6) {
  const out = []
  let rest = list
  while (rest.length) {
    const counts = new Map()
    const take = []
    const later = []
    for (const e of rest) {
      const c = counts.get(e.prefix) ?? 0
      if (take.length < window && c < perSet) {
        take.push(e)
        counts.set(e.prefix, c + 1)
      } else later.push(e)
    }
    out.push(...take)
    rest = later
  }
  return out
}

/** Handlers take (url) and return { status, body, headers }; server/app.js wraps them. */
export async function searchIconsRoute(url) {
  const q = String(url.searchParams.get('q') ?? '').trim()
  if (q.length < 2 || q.length > 80) return { status: 400, error: 'Search for at least 2 characters.' }
  const limit = Math.min(Math.max(Number(url.searchParams.get('limit')) || 36, 1), MAX_LIMIT)
  const offset = Math.min(Math.max(Number(url.searchParams.get('offset')) || 0, 0), 5000)
  const index = await loadIndex()
  const ranked = rankIcons(index, q)
  const icons = ranked.slice(offset, offset + limit).map((e) => {
    const s = index.bySet.get(e.prefix)
    return { id: e.id, name: e.words.join(' '), set: s.name, license: s.license }
  })
  return { status: 200, body: { icons, total: ranked.length } }
}

export async function iconSvgRoute(url) {
  const m = String(url.searchParams.get('id') ?? '').match(ID_RE)
  if (!m) return { status: 400, error: 'Unknown icon.' }
  const [, prefix, name] = m
  const index = await loadIndex()
  if (!index.bySet.get(prefix)?.nameSet.has(name)) return { status: 404, error: 'Icon not found.' }
  return { status: 200, svg: iconSvg(await loadSet(prefix), name) }
}

export async function iconSetsRoute() {
  const { sets } = await loadIndex()
  return {
    status: 200,
    body: {
      sets: sets.map((s) => ({ prefix: s.prefix, name: s.name, author: s.author, authorUrl: s.authorUrl, license: s.license, licenseUrl: s.licenseUrl, version: s.version, total: s.names.length })),
    },
  }
}

/**
 * A standalone SVG for one icon: 24px tall (width follows the aspect ratio) with a black fill,
 * so the importer reads real geometry rather than 1em or currentColor.
 */
export function iconSvg(set, name) {
  const v = set.icons[name]
  const [body, w, h, l, t] = typeof v === 'string' ? [v, set.w, set.h, 0, 0] : v
  const height = 24
  const width = Math.round((24 * w) / h * 1000) / 1000
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="${l} ${t} ${w} ${h}">` +
    body.replace(/currentColor/g, '#000000') +
    '</svg>'
  )
}
